function renderCheckFields(target,selected,keys){const el=$v(target);if(!el)return;el.innerHTML=keys.map(k=>`<label><input type="checkbox" data-dp-field="${k}" ${selected.includes(k)?'checked':''}> ${tr(...fieldLabels[k])}</label>`).join('');}
